WITH valid_products AS (SELECT * FROM products WHERE YEAR(launch_date) >= 2025), agg AS (SELECT CASE WHEN cost >= 640 THEN 'high' WHEN cost >= 260 THEN 'mid' ELSE 'low' END AS cost_bucket, SUM(stock_qty) AS total_stock_qty FROM valid_products GROUP BY CASE WHEN cost >= 640 THEN 'high' WHEN cost >= 260 THEN 'mid' ELSE 'low' END) SELECT cost_bucket, total_stock_qty FROM agg WHERE total_stock_qty >= 1700 ORDER BY cost_bucket
